/**
 * Cross-platform test vector `packages/test-vectors/vectors/agents/create-note.json`:
 * the exact Yjs state a create_note writes (and the delta of an edit_note
 * replace_text on the title). ios-editor and web-editor load it byte-exact to
 * check that opening such a note writes nothing.
 *
 * The file is generated by this test: `UPDATE_VECTORS=1 pnpm --filter @datascratch/agents test agent-vectors`.
 * Without the variable the test fails when the committed file differs.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { yFragmentToPM } from "@datascratch/shared/document";
import { describe, expect, it } from "vitest";
import * as Y from "yjs";
import { applyEdits, initNoteContent } from "../src/doc/edits.js";
import { noteToMarkdown } from "../src/doc/markdown-export.js";
import { titleBlockId } from "../src/testing/fixtures.js";
import { base64url } from "../src/util.js";

const PATH = fileURLToPath(new URL("../../test-vectors/vectors/agents/create-note.json", import.meta.url));

/** Deterministic ids, in the order the importer asks for them. */
const vid = (n: number) => `0192f3c4-0000-7000-8000-${n.toString(16).padStart(12, "0")}`;
const LINKED_NOTE = vid(0xa001);
const AGENT_EDIT = { agentId: vid(0xa002), at: "2026-10-26T12:00:00.000Z" };

const TITLE = "План на неделю";
const MARKDOWN = [
  "Короткое введение с **жирным**, *курсивом*, `кодом`, ==маркером== и ссылкой на [[План запуска]] #работа.",
  "",
  "> [!warning] ⚠️",
  "> Сроки сдвигаются — проверить до пятницы.",
  "",
  "| Задача | Ответственный | Статус |",
  "| :--- | :---: | ---: |",
  "| Дизайн | Аня | готово |",
  "| Сервер | Борис | в работе |",
  "",
  "- первый пункт",
  "- второй пункт",
  "  - вложенный",
  "",
  "1. раз",
  "2. два",
  "",
  "- [ ] Отправить отчёт ⏳ 2026-10-27 📅 2026-10-30",
  "- [x] Созвон с командой",
  "",
  "```ts",
  "const total = items.reduce((a, b) => a + b, 0);",
  "```",
  "",
  "$$",
  "E = mc^2",
  "$$",
  "",
  "Формула в строке: $a^2 + b^2 = c^2$.",
  "",
  "```mermaid",
  "graph TD; A-->B",
  "```",
].join("\n");

function build() {
  let n = 0;
  const newId = () => vid(0x1000 + ++n);
  const doc = new Y.Doc();
  doc.clientID = 1;
  // Exactly what AgentService.createNote does (D-45: no agentEdit marks in a note the agent created).
  initNoteContent(doc, TITLE, MARKDOWN, { agentEdit: null, newId, resolveNoteLink: (label) => (label === "План запуска" ? LINKED_NOTE : null) });
  const created = Y.encodeStateAsUpdate(doc);
  const createdContent = yFragmentToPM(doc.getXmlFragment("content"));
  const createdMarkdown = noteToMarkdown(doc);

  // The agent's edit is made on a fresh copy of the stored state, as AgentService.mutate does.
  const copy = new Y.Doc();
  copy.clientID = 2;
  Y.applyUpdate(copy, created);
  const before = Y.encodeStateVector(copy);
  const titleId = titleBlockId(copy);
  const op = { op: "replace_text" as const, blockId: titleId, find: "неделю", replace: "месяц" };
  applyEdits(copy, [op], { agentEdit: AGENT_EDIT, newId });
  const edit = Y.encodeStateAsUpdate(copy, before);

  return {
    version: 1,
    description:
      "A note exactly as the agent API writes it (create_note → initNoteContent, packages/agents) and the delta of an edit_note replace_text on its title. Decode `createNote.update` (Yjs update v1, clientID 1) into an empty doc: `content` (canonical PM JSON as in document/note.json), `meta` and the Markdown read_note returns must equal `expected`; opening the note must write nothing. Then apply `editTitle.update` (clientID 2): the title becomes “План на месяц” and the inserted text carries the agentEdit mark. Block ids are vid(0x1001…) in the order blocks are created; [[План запуска]] resolves to `linkedNoteId`.",
    input: { title: TITLE, markdown: MARKDOWN, linkedNoteId: LINKED_NOTE, agentEdit: null },
    createNote: {
      update: base64url(created),
      expected: { content: createdContent, meta: doc.getMap("meta").toJSON(), markdown: createdMarkdown },
    },
    editTitle: {
      operation: op,
      agentEdit: AGENT_EDIT,
      update: base64url(edit),
      expected: { content: yFragmentToPM(copy.getXmlFragment("content")), markdown: noteToMarkdown(copy) },
    },
  };
}

describe("agents test vector (create_note + replace_text on the title)", () => {
  const vector = build();
  const text = JSON.stringify(vector, null, 2) + "\n";

  it("is deterministic", () => {
    expect(JSON.stringify(build(), null, 2) + "\n").toBe(text);
  });

  it("matches the committed vector", () => {
    if (process.env.UPDATE_VECTORS) {
      mkdirSync(dirname(PATH), { recursive: true });
      writeFileSync(PATH, text);
    }
    expect(existsSync(PATH), "run UPDATE_VECTORS=1 pnpm --filter @datascratch/agents test agent-vectors").toBe(true);
    expect(readFileSync(PATH, "utf8")).toBe(text);
  });

  it("decodes to the expected note and title edit", () => {
    const doc = new Y.Doc();
    Y.applyUpdate(doc, Buffer.from(vector.createNote.update, "base64url"));
    expect(yFragmentToPM(doc.getXmlFragment("content"))).toEqual(vector.createNote.expected.content);
    // Re-encoding the decoded state gives the same bytes: nothing to write back.
    expect(base64url(Y.encodeStateAsUpdate(doc))).toBe(vector.createNote.update);
    Y.applyUpdate(doc, Buffer.from(vector.editTitle.update, "base64url"));
    const title = (yFragmentToPM(doc.getXmlFragment("content")).content ?? [])[0] as { content?: { text?: string; marks?: { type: string }[] }[] };
    expect(title.content!.map((t) => t.text).join("")).toBe("План на месяц");
    expect(title.content!.find((t) => t.text === "месяц")!.marks!.map((m) => m.type)).toContain("agentEdit");
    expect(vector.createNote.expected.markdown).toContain("[[План запуска]]");
  });
});
